"""GreenOS application catalog and client-side app windows."""

APPS_CSS = r'''
<style>
.app-grid{display:flex;flex-wrap:wrap;gap:24px;max-width:620px}.app-icon.extra{margin:0}.app-window{position:absolute;z-index:7;inset:12% 18%;display:grid;grid-template-rows:42px 1fr;overflow:hidden;border:1px solid var(--line);background:rgba(8,20,12,.98);box-shadow:0 24px 80px rgba(0,0,0,.5);animation:window-in .25s ease-out}.app-window.hidden{display:none}.app-window.small{inset:18% 30%}.app-window.wide{inset:10% 14%}.app-window-head{display:flex;align-items:center;padding:0 14px;border-bottom:1px solid var(--line);background:rgba(15,42,23,.94)}.app-window-title{flex:1;color:var(--green);font-size:12px}.app-window-head button{width:22px;height:22px;margin-left:7px;border:1px solid var(--line);color:var(--muted);background:transparent}.app-window-head button:hover{color:var(--ink);border-color:var(--green)}.app-content{min-height:0;overflow:auto;padding:22px}.app-content h2{margin:0 0 16px;color:var(--green);font-size:18px}.app-content p{color:var(--muted)}.app-content textarea,.app-content .terminal-input{width:100%;min-height:230px;resize:none;border:1px solid var(--line);padding:14px;outline:0;color:var(--ink);background:#06110a;font:14px "Courier New",monospace}.app-content textarea:focus,.app-content input:focus{border-color:var(--green)}.app-content input,.app-content select{border:1px solid var(--line);padding:10px;color:var(--ink);background:#06110a;outline:0}.app-button{border:1px solid var(--green);padding:10px 14px;color:var(--green);background:transparent}.app-button:hover{color:var(--bg);background:var(--green)}.app-row{display:flex;align-items:center;gap:10px;margin:10px 0}.terminal-output{height:240px;overflow:auto;margin-bottom:10px;padding:14px;border:1px solid var(--line);color:var(--green);background:#030804;white-space:pre-wrap}.file-list,.notification-list{display:grid;gap:8px}.file-item,.notification{padding:12px;border:1px solid var(--line);color:var(--ink);background:rgba(24,68,37,.35)}.clock-face{text-align:center;font-size:44px;color:var(--green);letter-spacing:.08em}.monitor-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.metric{padding:18px;border:1px solid var(--line);background:rgba(24,68,37,.3)}.metric strong{display:block;margin-top:8px;color:var(--green);font-size:24px}.toggle{accent-color:var(--green)}.store-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.store-card{padding:15px;border:1px solid var(--line);background:rgba(24,68,37,.3)}.store-card strong{display:block;color:var(--green);margin-bottom:6px}.game-board{display:grid;grid-template-columns:repeat(8,1fr);gap:4px;width:min(90vw,360px);margin:auto}.mine-cell{aspect-ratio:1;border:1px solid var(--line);color:var(--ink);background:#10281a;font-size:18px}.mine-cell.open{background:#1b4c2a}.two-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:6px;width:min(90vw,360px);margin:auto}.two-cell{aspect-ratio:1;display:grid;place-items:center;border:1px solid var(--line);color:var(--green);background:#10281a;font-size:22px}.two-cell.v2{color:var(--yellow);background:#274e2b}.two-cell.v4{color:#ff9f43;background:#38532b}.two-cell.v8{color:#ff5c5c;background:#4a3525}@media(max-width:700px){.app-window,.app-window.wide,.app-window.small{inset:8% 10px 12%}.monitor-grid,.store-grid{grid-template-columns:1fr}}
</style>
'''

